// ─ the gh-1406 required-reviewer clause (§7) ─

/**
 * Phase 0 — the required-reviewer pool clause: when the head's pool
 * outcome names required reviewers and one of them lacks a same-head PASS
 * marker, the merge is withheld (like red CI — gh-1406 §7). Reads the
 * SAME comments the hold-dedup phase needs (one getComments round-trip
 * when the caller threaded it; a self-read when not). Fail-open exactly:
 * no pool outcome on this head (legacy single-leg PRs) → proceed; no
 * getComments primitive → skip; a broken read throws through (fail-closed
 * like every census here). Returns true when the gate HELD on this clause.
 */
function poolPhase(io, owner, name, inp, out, comments) {
   var list = comments;
   if (list === undefined) {
       if (!io || typeof io.getComments !== 'function') {
           out.poolSkipped = true; // capability miss — the skip shape
           return false;
       }
       list = mergeVerdictGate.prCommentList(io.getComments, owner, name, inp.prNumber);
   }
   var state = reviewPoolMarkers.requiredReviewerHoldState(list, inp.logins || [], out.head, inp.nowIso);
   if (!state.applicable) return false;
   out.poolMissing = state.missing;
   if (state.missing.length === 0) return false;
   out.held = true;
