        var noExt = base.replace(/\.js$/, '');

        if (moduleMap[base]) return withModuleCompat(moduleMap[base]);
        if (moduleMap[noExt]) return withModuleCompat(moduleMap[noExt]);
        if (moduleMap['./' + base]) return withModuleCompat(moduleMap['./' + base]);

